        if arr:
            arrived = clean_loc(arr.group(1))
        for mo in re.finditer(r"On the ([^,]+), you see ([^.]*)\.", text):
            loc = clean_loc(mo.group(1))
            items_str = mo.group(2)
            items = []
            for p in re.split(r",\s*|\s+and\s+", items_str):
                p = p.strip().rstrip(".")
                if p:
                    items.append(p)
            contents[loc] = items
        pick = re.search(r"You pick up the (.+?) from the (.+?)\.", text)
        if pick:
            item = pick.group(1).strip()
            loc = clean_loc(pick.group(2))
            if loc in contents and item in contents[loc]:
                contents[loc].remove(item)
        mv = re.search(r"You move the (.+?) to the (.+?)\.", text)
        if mv:
            item = mv.group(1).strip()
            loc = clean_loc(mv.group(2))
            contents.setdefault(loc, [])
            if item not in contents[loc]:
                contents[loc].append(item)
        return contents, arrived

    # Use initial observation (room description) directly
    initial = env.observation
    if not re.search(r"you see", initial, re.IGNORECASE):
        initial = env.step("look")

    receptacles = []
    for tok in re.findall(r"\b([a-zA-Z]+(?:\s+[a-zA-Z]+)*\s+\d+)\b", initial):
        t = clean_loc(tok)
        if t and t not in receptacles:
            receptacles.append(t)

    all_contents = {}
    current_loc = None
    holding = None
    visited = set()

    init_contents, init_arr = parse_obs(initial)
    for k, v in init_contents.items():
        all_contents[k] = v
    if init_arr:
        current_loc = init_arr

    def do(cmd):
        nonlocal current_loc
        fb = env.step(cmd)
        c, a = parse_obs(fb)
        for k, v in c.items():
            all_contents[k] = v
        if a:
            current_loc = a
            visited.add(a)
        return fb

    def all_locs():
        locs = list(receptacles)
        for k in all_contents.keys():
            if k not in locs:
                locs.append(k)
        return locs

    def item_match(name):
        n = norm(name)
        return n == item_base or item_base in n or n in item_base

    def dest_match(name):
        n = norm(name)
        return n == dest_base or n.startswith(dest_base) or dest_base in n

    found_item = None
    found_loc = None
    for loc, items in all_contents.items():
        for it in items:
            if item_match(it):
                found_item = it
                found_loc = loc
                break
        if found_item:
            break

    # Explore receptacles using clean names (no leading "a" / "and")
    if not found_item:
        dest_candidates = [r for r in all_locs() if dest_match(r)]
        queue = deque()
        for d in dest_candidates:
            if d not in queue:
                queue.append(d)
        for r in all_locs():
            if r not in queue:
                queue.append(r)

        while not found_item and queue:
            loc = queue.popleft()
            if loc in visited:
                continue
            fb = do(f"go to {loc}")
            if "nothing happens" in fb.lower():
                visited.add(loc)
                continue
            for it in all_contents.get(loc, []):
                if item_match(it):
                    found_item = it
                    found_loc = loc
                    break
            if found_item:
                break
            if not all_contents.get(loc):
                do("look")
                for it in all_contents.get(loc, []):
                    if item_match(it):
                        found_item = it
                        found_loc = loc
                        break
                if found_item:
                    break

    if not found_item:
        inv = re.search(r"You are carrying (.+)\.", env.observation)
        if inv:
            for c in re.split(r",\s*|\s+and\s+", inv.group(1)):
                c = c.strip()
                if c and item_match(c):
                    found_item = c
                    holding = c
                    break

    if found_item and holding != found_item:
        if found_loc is not None:
            if current_loc != found_loc:
                do(f"go to {found_loc}")
            do(f"take {found_item} from {found_loc}")
            if "pick up" in env.observation.lower() or "take" in env.observation.lower():
                holding = found_item
        else:
            holding = found_item

    dest_candidates = [r for r in all_locs() if dest_match(r)]
    if dest_candidates:
        dest = dest_candidates[0]
    else:
        dest = None
        for r in all_locs():
            if r != found_loc:
                dest = r
                break

    if holding and dest:
        if current_loc != dest:
            do(f"go to {dest}")
        do(f"move {holding} to {dest}")
        if "move" not in env.observation.lower():
            do(f"move {holding} to {dest}")

    return env.observation
